text:
{
    "notes": [
        {"character": "沈知微", "kind": "background", "text": "前世死在十九岁那年的腊月。二叔卖了沈家老宅，陆家退了婚。", "quote": "她死在十九岁那年的腊月。二叔卖了沈家老宅，陆家退了婚，她抱着一包旧衣裳在当铺门口等了一夜。"},
        {"character": "沈知微", "kind": "wound", "text": "心软过，结果连命都赔了进去。", "quote": "前世她心软过，结果连命都赔了进去。"},
        {"character": "沈承业", "kind": "background", "text": "在城南的长乐赌坊欠了三百两银子，赌坊的刘三放过话，年前还不上，就剁他一只手。", "quote": "二叔在城南的长乐赌坊欠了三百两银子，赌坊的刘三放过话，年前还不上，就剁他一只手。"},
        {"character": "沈承业", "kind": "situation", "text": "穿着新做的狐皮袄子，脸上带着假笑。", "quote": "二叔穿着新做的狐皮袄子，脸上的笑比灵堂里的白幡还假。"},
        {"character": "沈知微", "kind": "goal", "text": "这一世，她只算自己的账。谁的情都不欠，谁的亏都不吃。", "quote": "这一世，她只算自己的账。谁的情都不欠，谁的亏都不吃，每一文钱都要花在刀刃上。"},
        {"character": "沈若兰", "kind": "relationship", "text": "是二叔的女儿。", "quote": "门外忽然响起一阵轻快的脚步声，接着是一个娇滴滴的声音：“堂姐醒了没有？我给你送姜汤来了。”"},
        {"character": "沈知微", "kind": "knowledge", "text": "母亲临终前亲手给她系上的玉佩边上缺了一个小口。", "quote": "还有贴身挂着的那块玉佩。玉佩是母亲临终前亲手给她系上的，边上缺了一个小口。"},
        {"character": "沈知微", "kind": "situation", "text": "枕头底下三十七文铜钱，一支母亲留下的银簪。", "quote": "她把这一世的家底摸了一遍：枕头底下三十七文铜钱，一支母亲留下的银簪，还有贴身挂着的那块玉佩。"}
    ]
}

{
    "notes": [
        {"character": "沈知微", "kind": "background", "text": "前世在周记当铺咽气", "quote": "城东的周记当铺是临川最大的当铺，也是前世她咽气的地方。"},
        {"character": "沈知微", "kind": "goal", "text": "还前世欠下的馒头钱，并保护自己", "quote": "前世的半个馒头要还，这一世，她也需要一双别人不会提防的眼睛。"},
        {"character": "沈知微", "kind": "relationship", "text": "与阿满有恩情", "quote": "“你叫什么？”“阿满。”“阿满，这二十文，是还你的。”"},
        {"character": "顾晏", "kind": "knowledge", "text": "知道沈知微前世的事情", "quote": "“正月里盐价要跌一半。手里有盐引的，最好年前出手。”"},
        {"character": "顾晏", "kind": "personality", "text": "冷面阎王", "quote": "伙计都愣了。顾晏是出了名的冷面阎王，连亲舅舅来借钱都要立字据。"}
    ]
}

{
  "summary": "沈知微在周记当铺用银簪换钱，并留下线索给阿满。",
  "tension": 2,
  "emotions": ["warmth", "suspense"],
  "hook": {"present": true, "quote": "不过沈姑娘若是缺钱，我可以另借你二两，不收利息，也不用抵押。"},
  "setups": [
    {"key": "正月里盐价要跌一半", "text": "正月初十盐价暴跌，临川好几家商号一夜之间倒了，周记也赔进去一大笔。这件事，她记了两辈子。", "quote": ""}
  ]
}

{
    "notes": [
        {"character": "刘三", "kind": "goal", "text": "要三百两银子", "quote": "三百两，腊月三十之前，少一个子儿，你这只右手就别要了。"},
        {"character": "沈承业", "kind": "wound", "text": "急着要钱", "quote": "二叔急着要钱，接下来一定会打老宅的主意。"},
        {"character": "沈知微", "kind": "goal", "text": "弄清楚地契在哪里", "quote": "她得赶在他前面，弄清楚地契在哪里。"},
        {"character": "沈若兰", "kind": "wound", "text": "父亲逼婚", "quote": "你一走，陆家那门亲事就是我的。"},
        {"character": "沈知微", "kind": "background", "text": "前世记忆", "quote": "梦里全是前世的雪。"},
        {"character": "陈伯", "kind": "relationship", "text": "听见动静，救了沈知微", "quote": "幸好老仆陈伯听见动静，拿竹竿把沈知微拉了上来。"}
    ]
}

{
  "summary": "沈若兰为了嫁陆明川而推妹妹沈知微落水，幸得陈伯相救。",
  "tension": 4,
  "emotions": ["suspense", "heartache"],
  "hook": {"present": true, "quote": "幸好老仆陈伯听见动静，拿竹竿把沈知微拉了上来。"},
  "setups": [
    {"key": "地契", "text": "二叔急着要钱，接下来一定会打老宅的主意。她得赶在他前面，弄清楚地契在哪里。",
     "quote": ""},
    {"key": "陆明川", "text": "陆明川来府里吊唁的那天，只看了堂姐一眼，就再也没往别处看过。",
     "quote": ""}
  ]
}

{
    "notes": [
        {"character": "沈知微", "kind": "goal", "text": "找到二叔的地契下落", "quote": "用五十文换老宅的下落，这笔买卖不亏。"},
        {"character": "小六", "kind": "wound", "text": "知道地契藏在何处", "quote": "二叔把地契藏在哪儿，他最有可能知道。"},
        {"character": "沈知微", "kind": "knowledge", "text": "二叔前天夜里出过门，怀里的匣子不见了", "quote": "我听见他跟车夫说，‘周记那边’。"},
        {"character": "周掌柜", "kind": "background", "text": "是城东周记当铺的掌柜", "quote": ""},
        {"character": "顾晏", "kind": "knowledge", "text": "知道暗柜上的字码锁密码是‘青雀’", "quote": "那两个字是‘青雀’，是我那过世的老伴儿的名字。"},
        {"character": "周掌柜", "kind": "relationship", "text": "与顾晏关系亲密，知晓秘密", "quote": "这件事只有你我两个人知道，连账房都不知道。"}
    ]
}

{
  "summary": "沈知微通过贿赂小六得知二叔将地契当了，同时顾晏在周记当铺得到了那只装有地契的匣子。",
  "tension": 3,
  "emotions": ["suspense", "tension"],
  "hook": {"present": true, "quote": "那两个字是‘青雀’，是我那过世的老伴儿的名字。"},
  "setups": [
    {"key": "青雀", "text": "暗柜上的字码锁密码", "quote": "那两个字是‘青雀’"}
  ]
}

{
    "notes": [
        {"character": "沈知微", "kind": "goal", "text": "取回沈家老宅的地契和当票。", "quote": "她取出那只匣子。匣子里是沈家老宅的地契，还有二叔按了手印的当票。"},
        {"character": "沈知微", "kind": "wound", "text": "前世二叔夺宅时第一个跑去讨赏的是春杏。", "quote": "可前世二叔夺宅的时候，第一个跑去二叔那里报信讨赏的，就是她。"},
        {"character": "沈知微", "kind": "relationship", "text": "春杏是母亲的陪嫁丫鬟。", "quote": "春杏是母亲的陪嫁丫鬟，"},
        {"character": "沈知微", "kind": "knowledge", "text": "地契和当票藏在周记当铺暗柜中。", "quote": "暗柜上挂着一把黄铜字码锁，要拨两个字。"},
        {"character": "沈知微", "kind": "situation", "text": "手头宽裕，可以给春杏银子。", "quote": "你去找二叔吧，他如今手头宽裕。"}
    ]
}

{
  "summary": "沈知微在周记当铺取走老宅的地契和当票，并拒绝了春杏的求助。",
  "tension": 2,
  "emotions": ["suspense", "tension"],
  "hook": {"present": true, "quote": "你去找二叔吧，他如今手头宽裕。"},
  "setups": [
    {"key": "地契", "text": "沈家老宅的地契", "quote": ""},
    {"key": "当票", "text": "二叔按了手印的当票", "quote": ""}
  ]
}

{
    "notes": [
        {"character": "沈知微", "kind": "goal", "text": "想要查清冤案", "quote": "听说了吗？朝廷派了巡察使杜大人下江南，专查各县的冤案，腊月十五就到咱们临川。"},
        {"character": "沈知微", "kind": "wound", "text": "心结是钱县令收受贿赂导致冤案", "quote": "去年他收了城南米行的银子，把人家的儿子关了半年……"},
        {"character": "沈知微", "kind": "situation", "text": "手头紧张，需要借钱或当东西", "quote": "回府之前，沈知微让小桃先走，自己绕道去了一趟周记当铺，在后堂和顾晏说了半个时辰的话。出来的时候，她怀里的当票和一张写好的状纸都不见了。"},
        {"character": "沈知微", "kind": "relationship", "text": "与陆明川有利益往来", "quote": "那天夜里，后窗响了三下。阿满扒着窗台，压低嗓子：“姐姐，前天夜里陆家公子来过，从二爷书房的后门走的。”"},
        {"character": "沈知微", "kind": "knowledge", "text": "十五日有重要安排", "quote": "回府的路上开始飘雪。沈知微走得很慢，一路都在算日子。"},
        {"character": "阿满", "kind": "relationship", "text": "与沈知微关系亲密", "quote": "那天夜里，后窗响了三下。阿满扒着窗台，压低嗓子：“姐姐，前天夜里陆家公子来过，从二爷书房的后门走的。”"},
        {"character": "沈承业", "kind": "relationship", "text": "与沈知微关系亲密", "quote": "回府之前，沈知微让小桃先走，自己绕道去了一趟周记当铺，在后堂和顾晏说了半个时辰的话。"},
        {"character": "陆明川", "kind": "relationship", "text": "与沈承业有利益往来", "quote": "那天夜里，后窗响了三下。阿满扒着窗台，压低嗓子：“姐姐，前天夜里陆家公子来过，从二爷书房的后门走的。”"},
        {"character": "沈知微", "kind": "personality", "text": "谨慎小心", "quote": "回府的路上开始飘雪。沈知微走得很慢，一路都在算日子。"}
    ]
}

{
  "summary": "沈知微得知朝廷巡察使即将到访临川，并且收到了关于二叔陆明川的可疑消息。",
  "tension": 3,
  "emotions": ["suspense", "tension"],
  "hook": {"present": true, "quote": "十五。正好。"},
  "setups": [
    {"key": "状纸", "text": "写好的状纸都不见了", "quote": ""},
    {"key": "巡察使", "text": "朝廷派了巡察使杜大人下江南，专查各县的冤案", "quote": ""},
    {"key": "陆明川", "text": "今晚二爷又请县衙的人吃酒，他在窗外听见了，说十五那天，要‘请大小姐去公堂上说说话’", "quote": ""}
  ]
}

{
    "notes": [
        {"character": "沈知微", "kind": "goal", "text": "要告的是有人勾结县衙，强夺孤女的家产", "quote": "民女要告的，不是偷盗，是有人勾结县衙，强夺孤女的家产。"},
        {"character": "沈知微", "kind": "relationship", "text": "母亲救过顾晏", "quote": "十年前城东那场大火，我被困在柴房里，是你母亲冲进去把我背出来的。"},
        {"character": "钱县令", "kind": "situation", "text": "被革职押回府城听审", "quote": "杜大人当堂判沈知微无罪，革了钱县令的职，押回府城听审。"},
        {"character": "顾晏", "kind": "knowledge", "text": "认出沈知微拿去当的银簪", "quote": "那天你拿来当的那支银簪，我一眼就认出来了。"},
        {"character": "顾晏", "kind": "relationship", "text": "救过顾晏", "quote": "十年前城东那场大火，我被困在柴房里，是你母亲冲进去把我背出来的。"}
    ]
}

{
  "summary": "沈知微被诬告偷盗家产，在公堂上揭露真相并获得巡察使的支持，最终无罪释放。",
  "tension": 4,
  "emotions": ["thrill", "suspense"],
  "hook": {"present": true, "quote": "你为什么帮我？那天在当铺，你借钱给我，连抵押都不要。"},
  "setups": [
    {"key": "银簪", "text": "认出沈知微的银簪是十年前救他的恩人所赠", "quote": "那天你拿来当的那支银簪，我一眼就认出来了。"}
  ]
}

{
    "notes": [
        {"character": "沈承业", "kind": "goal", "text": "不再有东西可卖", "quote": "地契回到了沈知微手里，二叔再也没有东西可卖。"},
        {"character": "刘三", "kind": "situation", "text": "带着人堵了沈家的大门", "quote": "腊月十八，长乐赌坊的刘三带着人堵了沈家的大门。"},
        {"character": "沈知微", "kind": "wound", "text": "二叔已经动手了，父亲的死不是意外", "quote": "你父亲的死，不是意外。"},
        {"character": "陆明川", "kind": "knowledge", "text": "周记守夜的伙计是他表舅", "quote": "周记守夜的伙计是你表舅；"},
        {"character": "沈知微", "kind": "goal", "text": "把账算清楚，谁欠她的都要还回来", "quote": "‘先把账算清楚。谁欠我的，一笔一笔，都要还回来。’她对自己说，"},
        {"character": "陈伯", "kind": "relationship", "text": "带进来一张字条", "quote": "前一天夜里，陈伯从后门带进来一张字条，是顾晏的笔迹，只有三行：报信的是陆明川；周记守夜的伙计是他表舅；陆家欠沈承业一百两。"},
        {"character": "沈知微", "kind": "personality", "text": "冷静、理智", "quote": "‘陆公子，那天是谁去给我二叔报信，说地契是我从当铺取走的？’"}
    ]
}

{
  "summary": "沈知微在得知陆明川背叛后前往裕丰钱庄取回母亲留下的玉佩和信件，并决定清算所有恩怨。",
  "tension": 4,
  "emotions": ["suspense", "anger"],
  "hook": {"present": true, "quote": "谁欠我的，一笔一笔，都要还回来。"},
  "setups": [
    {"key": "玉佩", "text": "母亲留下的玉佩", "quote": ""},
    {"key": "存票和信件", "text": "母亲的遗言和一千两的存票", "quote": ""}
  ]
}

